from typing import List

def can_form_arithmetic_progression(nums: List[int]) -> bool:
    """
    Determines if the list forms an arithmetic progression after permuting its elements.
    """
    if len(nums) < 2:
        return False

    nums.sort()
    diff = nums[1] - nums[0]

    for i in range(2, len(nums)):
        if nums[i] - nums[i - 1] != diff:
            return False

    return True

