def calculate_depth(d, current_depth=1):
    """
    Returns the maximum depth of the nested dictionary.
    """
    if not isinstance(d, dict) or not d:
        return current_depth
    return max(calculate_depth(v, current_depth + 1) if isinstance(v, dict) else current_depth for v in d.values())

