def reverse_segments(inputArray):
    result = []
    start = 0
    for i in range(len(inputArray)):
        if inputArray[i] == 0:
            if start < i:
                result.extend(inputArray[start:i][::-1])
            result.append(0)
            start = i + 1
    if start < len(inputArray):
        result.extend(inputArray[start:][::-1])    
    return result

