from typing import List

def can_reach_end(grid: List[List[str]]) -> bool:
    """
    Returns True if there is a path from the top-left corner to the bottom-right corner
    of the grid only moving through 'O' spaces (open spaces) and avoiding 'X' (obstructions).
    """
    if not grid or grid[0][0] == 'X' or grid[-1][-1] == 'X':
        return False

    n, m = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)] # right, down, left, up

    def dfs(x, y):
        if x == n - 1 and y == m - 1:
            return True
        grid[x][y] = 'X'  # mark as visited
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 'O':
                if dfs(nx, ny):
                    return True
        return False

    return dfs(0, 0)

