def spiral_order(matrix):
    """
    Returns the elements of the matrix in spiral order.

    Args:
    matrix: 2D list of integers

    Returns:
    list of integers in spiral order
    """
    if not matrix:
        return []

    spiral = []
    while matrix:
        # Take the first row
        spiral.extend(matrix.pop(0))

        # Take the last element of each remaining row
        if matrix and matrix[0]:
            for row in matrix:
                spiral.append(row.pop())

        # Take the last row in reverse order
        if matrix:
            spiral.extend(matrix.pop()[::-1])

        # Take the first element of each remaining row in reverse order
        if matrix and matrix[0]:
            for row in matrix[::-1]:
                spiral.append(row.pop(0))

    return spiral

def calculate_maximum_bonus(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        production_numbers = test_cases[i][1]

        if N < 2:
            results.append(0)
            continue

        max_increase = 0
        for j in range(1, N):
            increase = production_numbers[j] - production_numbers[j - 1]
            if increase > max_increase:
                max_increase = increase

        results.append(max_increase)

    return results

from typing import List

def letter_combinations(digits: str) -> List[str]:
    if not digits:
        return []

    # Mapping of digits to letters
    digit_to_char = {
        '2': 'abc', '3': 'def', '4': 'ghi',
        '5': 'jkl', '6': 'mno', '7': 'pqrs',
        '8': 'tuv', '9': 'wxyz'
    }

    # Helper function to generate combinations
    def backtrack(index: int, path: str):
        if index == len(digits):
            combinations.append(path)
            return
        possible_chars = digit_to_char[digits[index]]
        for char in possible_chars:
            backtrack(index + 1, path + char)

    combinations = []
    backtrack(0, "")
    return combinations

def longest_substring(s: str) -> int:
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_map = {}
    left = 0
    max_length = 0

    for right, char in enumerate(s):
        if char in char_map and char_map[char] >= left:
            left = char_map[char] + 1
        char_map[char] = right
        max_length = max(max_length, right - left + 1)

    return max_length

