def min_operations(s1: str, s2: str) -> int:
    """
    Calculate the minimum number of operations needed to transform s1 into s2.
    Operations include insertion, deletion, and replacement of characters.
    """
    m, n = len(s1), len(s2)

    # Create a 2D array to store the minimum number of operations for each subproblem
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill in the base cases
    # If s1 is empty, we need to insert all characters of s2
    for j in range(n + 1):
        dp[0][j] = j

    # If s2 is empty, we need to remove all characters of s1
    for i in range(m + 1):
        dp[i][0] = i

    # Fill the dp array using the previously computed states
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation needed
            else:
                dp[i][j] = min(dp[i - 1][j],    # Remove from s1
                               dp[i][j - 1],    # Insert into s1
                               dp[i - 1][j - 1] # Replace in s1
                               ) + 1

    return dp[m][n]

