def flatten_nested_list(nested_list):
    """
    Flattens a nested list into a single list of integers, preserving order.

    :param nested_list: List containing integers or nested lists
    :return: Flattened list of integers
    """
    flat_list = []

    def flatten(sublist):
        for item in sublist:
            if isinstance(item, list):
                flatten(item)
            else:
                flat_list.append(item)

    flatten(nested_list)
    return flat_list

