def is_prime(n):
    """
    Returns True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def filter_primes(numbers):
    """
    Returns a new list containing only the prime numbers from the given list 'numbers'.
    """
    return [num for num in numbers if is_prime(num)]

