from typing import List, Dict

def update_books(logs: List[str]) -> Dict[str, int]:
    inventory = {}

    for log in logs:
        action, details = log.split(" ", 1)
        title, author = details.split('" by ')
        title = title.strip('"')
        author = author.strip()

        book_key = f'{title} by {author}'

        if action == "borrowed":
            inventory[book_key] = inventory.get(book_key, 0) - 1
        elif action == "returned":
            inventory[book_key] = inventory.get(book_key, 0) + 1

    return inventory

