def days_to_reach_max_height(T, test_cases):
    results = []
    for H, G, L in test_cases:
        if H >= L:
            results.append(0)
        elif G == 0:
            results.append('Infinity')
        else:
            days = (L - H + G - 1) // G  # This ensures we use ceiling division
            results.append(days)
    return results

