def process_queries(M, N, grid, queries):
    def bfs_max_value(i, j):
        from collections import deque
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        visited = [[False] * N for _ in range(M)]
        max_value = grid[i][j]
        queue = deque([(i, j)])
        visited[i][j] = True

        while queue:
            cur_i, cur_j = queue.popleft()
            for di, dj in directions:
                ni, nj = cur_i + di, cur_j + dj
                if 0 <= ni < M and 0 <= nj < N and not visited[ni][nj] and grid[ni][nj] >= grid[cur_i][cur_j]:
                    visited[ni][nj] = True
                    max_value = max(max_value, grid[ni][nj])
                    queue.append((ni, nj))

        return max_value

    results = []
    for query in queries:
        if query[0] == 1:
            _, i_q, j_q, val_q = query
            grid[i_q - 1][j_q - 1] = val_q
        elif query[0] == 2:
            _, i_q, j_q = query
            results.append(bfs_max_value(i_q - 1, j_q - 1))

    return results

def length_of_longest_substring(s):
    """
    Finds the length of the longest substring without repeating characters.
    """
    char_map = {}
    left = 0
    longest = 0

    for right, char in enumerate(s):
        if char in char_map and char_map[char] >= left:
            left = char_map[char] + 1
        char_map[char] = right
        longest = max(longest, right - left + 1)

    return longest

