def average_in_range(numbers):
    """
    Returns the average of the numbers that are in the range 10 to 20 (inclusive).
    If no numbers are in this range, return None.
    """
    in_range = [num for num in numbers if 10 <= num <= 20]
    if not in_range:
        return None
    return sum(in_range) / len(in_range)

