def findPrimes(n):
    """
    Returns a list of all prime numbers less than n.
    """
    if n <= 2:
        return []

    # Sieve of Eratosthenes
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False

    return [i for i in range(n) if is_prime[i]]

def has_increasing_triplet(T, test_cases):
    results = []

    for i in range(T):
        N, A = test_cases[i]
        if N < 3:
            results.append("NO")
            continue

        first = float('inf')
        second = float('inf')

        for number in A:
            if number <= first:
                first = number
            elif number <= second:
                second = number
            else:
                results.append("YES")
                break
        else:
            results.append("NO")

    return results

