def contains_anagram(s1, s2):
    from collections import Counter

    len_s1, len_s2 = len(s1), len(s2)

    if len_s1 > len_s2:
        return False

    s1_count = Counter(s1)
    window_count = Counter(s2[:len_s1])

    for i in range(len_s2 - len_s1 + 1):
        if i > 0:
            # Slide the window: remove one preceding character and add a new one
            window_count[s2[i - 1]] -= 1
            if window_count[s2[i - 1]] == 0:
                del window_count[s2[i - 1]]
            window_count[s2[i + len_s1 - 1]] += 1

        if window_count == s1_count:
            return True

    return False

