def num_distinct_regions(grid):
    """
    Returns the number of distinct regions of '1's in the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]

    def dfs(x, y):
        # Stack for Depth-First Search (DFS)
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == '1':
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    region_count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and not visited[i][j]:
                region_count += 1
                visited[i][j] = True
                dfs(i, j)

    return region_count

