def smallest_lexicographic_substring(s, k):
    """
    Returns the smallest lexicographically substring of length k from string s.
    If there is no such substring, return an empty string.
    """
    if len(s) < k or k <= 0:
        return ""

    min_substring = s[:k]
    for i in range(1, len(s) - k + 1):
        current_substring = s[i:i+k]
        if current_substring < min_substring:
            min_substring = current_substring

    return min_substring

