from collections import Counter, deque
import heapq

def rearrange_string(s, k):
    if k == 0:
        return s

    count = Counter(s)
    max_heap = [(-value, key) for key, value in count.items()]
    heapq.heapify(max_heap)

    queue = deque()

    result = []

    while max_heap:
        freq, char = heapq.heappop(max_heap)
        result.append(char)

        queue.append((char, freq + 1))

        if len(queue) >= k:
            front_char, front_freq = queue.popleft()
            if front_freq < 0:
                heapq.heappush(max_heap, (front_freq, front_char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

def smallest_friendship_closure(n, friendships):
    from collections import defaultdict, deque

    def bfs(start):
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    if not friendships and n > 1:  # No friendships at all but multiple employees
        return -1

    graph = defaultdict(list)
    for a, b in friendships:
        graph[a].append(b)
        graph[b].append(a)

    visited = set()
    components = 0

    for employee in range(n):
        if employee not in visited:
            components += 1
            bfs(employee)

    if components > 1:
        return -1

    return n

