def remove_duplicates(s):
    """
    Returns a new string with characters from s that appear only once in the 
    order they first appear in s.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            result.append(char)
            seen.add(char)
    return ''.join(result)

