def can_travel(routes, startCity, destinationCity):
    from collections import defaultdict, deque

    if startCity == destinationCity:
        return True

    # Create adjacency list
    graph = defaultdict(list)
    for cityA, cityB in routes:
        graph[cityA].append(cityB)
        graph[cityB].append(cityA)

    # Perform BFS to find a path from startCity to destinationCity
    visited = set()
    queue = deque([startCity])

    while queue:
        current_city = queue.popleft()
        if current_city == destinationCity:
            return True
        if current_city not in visited:
            visited.add(current_city)
            for neighbor in graph[current_city]:
                if neighbor not in visited:
                    queue.append(neighbor)

    return False

def has_pair_with_sum(arr, x):
    """
    Returns True if there exists a pair of elements in the array whose sum is equal to x.
    """
    seen = set()
    for num in arr:
        if x - num in seen:
            return True
        seen.add(num)
    return False

