def num_islands(grid):
    """
    Returns the number of distinct islands in the grid.
    An island is a group of connected '1's (occupied land) connected horizontally or vertically.
    """
    if not grid:
        return 0

    def dfs(x, y):
        if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] == '0':
            return
        grid[x][y] = '0'  # Mark the land as visited
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    islands_count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                islands_count += 1
                dfs(i, j)
    return islands_count

