def min_final_digits(s):
    """
    Reduce the number string `s` by replacing non-empty substrings with their digit sum until 
    the sum is a single digit. Returns the minimum number of digits remaining.
    """
    # Calculate the sum of all digits in the original string
    total_sum = sum(int(c) for c in s)

    # Return the sum of digits repeated until a single digit result is obtained
    def digit_root(n):
        while n > 9:
            n = sum(int(c) for c in str(n))
        return n

    return 1 if digit_root(total_sum) < 10 else len(str(digit_root(total_sum)))

