def calculate_total_time_in_building(logs):
    """
    Calculates the total time each employee spent inside the building.

    Args:
    logs (list): List of tuples containing the (timestamp, employee_id, action).

    Returns:
    dict: Dictionary with employee_id as the key and total time spent in the building as the value.
    """
    total_time = {}
    entry_time = {}

    for timestamp, employee_id, action in logs:
        if action == 'enter':
            entry_time[employee_id] = timestamp
        elif action == 'exit':
            if employee_id in entry_time:
                time_spent = timestamp - entry_time[employee_id]
                if employee_id in total_time:
                    total_time[employee_id] += time_spent
                else:
                    total_time[employee_id] = time_spent
                del entry_time[employee_id]

    return total_time

