def minTime(nums, n):
    def canDistribute(nums, n, maxTime):
        total, count = 0, 1
        for num in nums:
            total += num
            if total > maxTime:
                total = num
                count += 1
                if count > n:
                    return False
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if canDistribute(nums, n, mid):
            right = mid
        else:
            left = mid + 1
    return left

