from typing import List

def max_rectangle_area(heights: List[int]) -> int:
    """
    Finds the maximum rectangular area that can be formed using
    one or more consecutive buildings given their heights.
    """
    n = len(heights)
    if n == 0:
        return 0

    max_area = 0
    stack = []

    for i in range(n):
        while stack and heights[stack[-1]] > heights[i]:
            h = heights[stack.pop()]
            if stack:
                width = i - stack[-1] - 1
            else:
                width = i
            max_area = max(max_area, h * width)
        stack.append(i)

    while stack:
        h = heights[stack.pop()]
        if stack:
            width = n - stack[-1] - 1
        else:
            width = n
        max_area = max(max_area, h * width)

    return max_area

