def max_length_equal_ones_negones(arr):
    """
    Returns the maximum length of contiguous subarray with an equal number of 1s and -1s.
    """
    if not arr:
        return 0

    # Dictionary to store the first occurrence of cumulative sums
    sum_dict = {0: -1}
    max_length, cum_sum = 0, 0

    for i, num in enumerate(arr):
        cum_sum += 1 if num == 1 else -1

        if cum_sum in sum_dict:
            max_length = max(max_length, i - sum_dict[cum_sum])
        else:
            sum_dict[cum_sum] = i

    return max_length

