def max_score(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        values = test_cases[i][1]
        specials = test_cases[i][2]

        max_score = 0
        for j in range(N):
            if specials[j] == 1:
                max_score = max(max_score, 2 * values[j])
            else:
                max_score = max(max_score, values[j])
        results.append(max_score)
    return results

